_startSessionsSync() {
  var self = this;
  if (self._sessionsSyncTimer) return; // already running
  // Claim window-level sync ownership so stale instances from hot-reloads cannot race us.
  window.__yupKbSyncOwner = self;
  // Run immediately once, then every 5 minutes. Store both handles so onunload can cancel.
  self._sessionsSyncInitTimer = setTimeout(function () {
    self._sessionsSyncInitTimer = null;
    if (window.__yupKbSyncOwner !== self) return; // superseded by a newer instance
    self._scanAndUploadSessions();
  }, 10000);
  self._sessionsSyncTimer = setInterval(function () {
    if (window.__yupKbSyncOwner !== self) return; // superseded
    self._scanAndUploadSessions();
  }, 5 * 60 * 1000);
}

patches.after:
_startSessionsSync() {
  throw new Error("会话归档暂不支持，其他知识库功能可用");
}

