// Option 1: recent/current directories from alwith stores
// Primary: settings.json → window.scopedState → lastOpenedWorkspace.path (most reliable)
// Fallback: settings.json → recentWorkspaces[0] (recently opened)
// Last resort: parse workspace.json keys to collect folder paths
var _recentPaths = []; // ordered: most-likely-current first
try {
  var _appData = await window.__TAURI_INTERNALS__.invoke("plugin:path|resolve_directory", { directory: 4 });
  var _appId = "ai.alwith.desktop";

  // ① Primary: settings.json → window.scopedState (most accurate for current window)
  try {
    var _settingsPath = _appData + "/" + _appId + "/settings.json";
    var _settingsArr = await window.__TAURI_INTERNALS__.invoke("plugin:fs|read_text_file", { path: _settingsPath, options: {} });
    var _settingsBytes = _settingsArr instanceof ArrayBuffer ? _settingsArr : Uint8Array.from(_settingsArr);
    var _settingsData = JSON.parse(new TextDecoder("utf-8").decode(_settingsBytes));

    // Extract from window.scopedState (each window's lastOpenedWorkspace.path)
    var _scopedState = _settingsData["window.scopedState"] || {};
    var _scopedPaths = [];
    Object.values(_scopedState).forEach(function(v) {
      if (v && v.lastOpenedWorkspace && v.lastOpenedWorkspace.path) {
        var p = v.lastOpenedWorkspace.path;
        if (!_scopedPaths.includes(p)) _scopedPaths.push(p);
      }
    });

    // If we found scoped paths, use them (most recent first based on object iteration order)
    if (_scopedPaths.length > 0) {
      _recentPaths = _scopedPaths;
    } else if (_settingsData.recentWorkspaces && _settingsData.recentWorkspaces.length > 0) {
      // Fallback to recentWorkspaces array
      _recentPaths = _settingsData.recentWorkspaces.slice();
    }
  } catch (_e1) {}

  // ② Last resort: parse workspace.json keys (folder:/path:setting → extract path)
  if (_recentPaths.length === 0) {
    try {
      var _wsPath = _appData + "/" + _appId + "/workspace.json";
      var _wsArr = await window.__TAURI_INTERNALS__.invoke("plugin:fs|read_text_file", { path: _wsPath, options: {} });
      var _wsBytes = _wsArr instanceof ArrayBuffer ? _wsArr : Uint8Array.from(_wsArr);
      var _wsData = JSON.parse(new TextDecoder("utf-8").decode(_wsBytes));
      var _seen = {};
      Object.keys(_wsData).forEach(function(k) {
        var m = k.match(/^folder:(.+):[^:]+$/);
        if (m && !_seen[m[1]]) { _seen[m[1]] = true; _recentPaths.push(m[1]); }
      });
    } catch (_e2) {}
  }
} catch (_e) {}

