async _autoLinkSessionsForWs(ws) {
  if (!window.__TAURI_INTERNALS__) return;
  try {
    var home = await _fsHomeDir();
    var alwithRoot = await _fsJoin(home, ".alwith", "projects");
    // Scope to the vault-dir that matches ws.localPath (same logic as _discoverSessions)
    var scanRoot = alwithRoot;
    if (ws.localPath) {
      var vaultDir = ws.localPath.replace(/\\/g, "/").replace(/\//g, "-");
      var candidate = alwithRoot + "/" + vaultDir;
      try { await _fsStat(candidate); scanRoot = candidate; } catch (_e) {}
    }
    // One Tauri invoke returns all sessions with title, modified_ms
    var entries = await _tauriInvoke("list_sessions", { baseDir: scanRoot });
    // Use modified_ms: include sessions active in the last 7 days
    var threshold = Date.now() - 7 * 24 * 60 * 60 * 1000;
    var linked = new Set(ws.linkedSessionDirs);
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (e.kind !== "session") continue;
      if ((e.modified_ms || 0) >= threshold) linked.add(e.path);
    }
    ws.linkedSessionDirs = Array.from(linked).slice(-200);
  } catch (_e) {}
}

