async _discoverSessions(ws) {
  var results = [];
  if (!window.__TAURI_INTERNALS__) return results;
  try {
    var home = await _fsHomeDir();
    var alwithRoot = await _fsJoin(home, ".alwith", "projects");

    // Derive vault-dir name for plugin-side filtering (same encoding alwith uses)
    var vaultDir = "";
    if (ws.localPath) {
      vaultDir = ws.localPath.replace(/\\/g, "/").replace(/\//g, "-");
    }

    // list_sessions expects the projects root — it iterates subdirectories as
    // project dirs. Always pass alwithRoot; filter by project_dir on our side.
    var entries = await _tauriInvoke("list_sessions", { baseDir: alwithRoot });
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (e.kind !== "session") continue; // skip subagent / tool-result children
      if (vaultDir && e.project_dir !== vaultDir) continue;
      results.push({ dir: e.path, title: e.title || e.id.slice(0, 8) + "…", ctimeMs: e.modified_ms || 0 });
    }
    results.sort(function (a, b) { return b.ctimeMs - a.ctimeMs; });
  } catch (_e) {}
  return results;
}

