// Step 4: upload linked sessions
// linkedSessionDirs stores full absolute paths to .jsonl files,
// e.g. /Users/x/.alwith/projects/-Users-x-Desktop-test/uuid.jsonl
cb({ phase: "sessions" });
var sessionsFolderId = null;
var sessionsEnsured = false;
for (var si = 0; si < ws.linkedSessionDirs.length; si++) {
  var sessionPath = ws.linkedSessionDirs[si];
  if (!sessionPath || !sessionPath.endsWith(".jsonl")) continue;
  var sParts = sessionPath.replace(/\\/g, "/").split("/");
  var sFileName = sParts[sParts.length - 1];
  var sUuid = sFileName.replace(/\.jsonl$/i, "");
  var sDirPath = sParts.slice(0, -1).join("/");
  var isPrivate = false;
  try { isPrivate = await _fileExists(sDirPath + "/" + sUuid + ".private"); } catch (_e) {}
  if (isPrivate) continue;
  var rawC;
  try { rawC = await _fsReadTextFile(sessionPath); } catch (_e) { continue; }
  var filteredSes = _filterJsonlForArchive(rawC);
  if (!filteredSes.kept) continue;
  var sesSha;
  try { sesSha = await _sha256Hex(filteredSes.jsonl); } catch (_e) { continue; }
  var sesKey = "sessions/" + sFileName; // cache key always uses UUID filename
  var sesCached = ws.uploadedFiles[sesKey];
  if (sesCached && sesCached.sha === sesSha) continue;

  // Build a human-readable display name from session content
  var sesDisplayName = sFileName;
  try {
    var sesLines = rawC.split("\n");
    var sesDate = "";
    var sesTitle = "";
    for (var sli = 0; sli < Math.min(sesLines.length, 10); sli++) {
      var sln = sesLines[sli].trim();
      if (!sln) continue;
      var sobj = JSON.parse(sln);
      if (!sesDate && sobj && sobj.timestamp) {
        sesDate = new Date(sobj.timestamp).toISOString().slice(0, 10);
      }
      if (!sesTitle && sobj && sobj.type === "user" && sobj.message) {
        var sc = sobj.message.content;
        if (typeof sc === "string" && sc.trim()) {
          sesTitle = sc.trim().replace(/[\r\n\s]+/g, " ").replace(/[/\\:*?"<>|]/g, "");
          if (sesTitle.length > 40) sesTitle = sesTitle.slice(0, 40);
        }
      }
      if (sesDate && sesTitle) break;
    }
    if (sesTitle) sesDisplayName = (sesDate ? sesDate + "_" : "") + sesTitle + ".jsonl";
  } catch (_e) {}

  if (!sessionsEnsured) {
    try {
      var sfr = await fetch(base + "/api/v1/folders/ensure", {
        method: "POST",
        headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json" },
        body: JSON.stringify({ projectId: ws.yupProjectId, parentId: ws.yupWorkspaceFolderId, relativePath: "sessions" })
      });
      if (sfr.ok) sessionsFolderId = (await sfr.json()).data;
    } catch (_e) {}
    sessionsEnsured = true;
  }

  var sesBlob = new Blob([filteredSes.jsonl], { type: "application/octet-stream" });
  var sesFd = new FormData();
  sesFd.append("file", sesBlob, sesDisplayName);
  var sesResp;
  if (sesCached && sesCached.fileId) {
    sesResp = await fetch(base + "/api/v1/files/" + sesCached.fileId + "/upload-version", {
      method: "POST", headers: { "Authorization": "Bearer " + token }, body: sesFd
    });
    if (sesResp.status === 404) sesCached = null;
  }
  if (!sesCached || !sesCached.fileId) {
    sesResp = await fetch(
      base + "/api/v1/files/upload?projectId=" + ws.yupProjectId +
      (sessionsFolderId ? "&folderId=" + sessionsFolderId : "") +
      "&name=" + encodeURIComponent(sesDisplayName),
      { method: "POST", headers: { "Authorization": "Bearer " + token }, body: sesFd }
    );
  }
  if (sesResp && sesResp.ok) {
    var sesJ = await sesResp.json();
    ws.uploadedFiles[sesKey] = { sha: sesSha, fileId: sesJ && sesJ.data && sesJ.data.fileId, mtime: Date.now() };
  }
}
